// Icons of track T5 readers (epub, pptx). Draw them with SvgIcon from './svgIcon' (not from MobileIcons, which
// imports this folder's index). File-type pictures go in the map below.
// The EPUB and PPTX file pictures are the desktop ones (generated by tools/gen-file-association-icons.mjs),
// the same family as the mobile HWP and Markdown pictures.
import fileEpubSvg from '../../../../../shell/src/renderer/src/assets/file-epub.svg'
import filePptxSvg from '../../../../../shell/src/renderer/src/assets/file-pptx.svg'
import { SvgIcon, type IconProps } from './svgIcon'
import type { DocTypeIconMap } from './types'

export const readersDocTypeIcons: DocTypeIconMap = { epub: fileEpubSvg, pptx: filePptxSvg }

/** Contents (EPUB table of contents). */
export function IconReaderToc(props: IconProps) {
  return (
    <SvgIcon {...props}>
      <line x1="9" y1="6" x2="20" y2="6" />
      <line x1="9" y1="12" x2="20" y2="12" />
      <line x1="9" y1="18" x2="20" y2="18" />
      <circle cx="4.5" cy="6" r="1" />
      <circle cx="4.5" cy="12" r="1" />
      <circle cx="4.5" cy="18" r="1" />
    </SvgIcon>
  )
}

/** Search in the book or deck. */
export function IconReaderSearch(props: IconProps) {
  return (
    <SvgIcon {...props}>
      <circle cx="11" cy="11" r="7" />
      <line x1="20" y1="20" x2="16.2" y2="16.2" />
    </SvgIcon>
  )
}

/** Reading settings (text size, line spacing, background): a large and a small letter A. */
export function IconReaderSettings(props: IconProps) {
  return (
    <SvgIcon {...props}>
      <path d="M3 19l5-14 5 14" />
      <path d="M4.8 14h6.4" />
      <path d="M14 19l3.5-9 3.5 9" />
      <path d="M15.2 16h4.6" />
    </SvgIcon>
  )
}

/** Speaker notes: a sheet with a folded corner and two lines. */
export function IconReaderNotes(props: IconProps) {
  return (
    <SvgIcon {...props}>
      <path d="M5 4h14a1 1 0 0 1 1 1v10l-5 5H5a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1z" />
      <path d="M20 15h-4a1 1 0 0 0-1 1v4" />
      <line x1="8" y1="9" x2="16" y2="9" />
      <line x1="8" y1="13" x2="12" y2="13" />
    </SvgIcon>
  )
}

/** Present full screen: a screen on a stand with a play mark. */
export function IconReaderPresent(props: IconProps) {
  return (
    <SvgIcon {...props}>
      <rect x="2" y="3" width="20" height="14" rx="2" />
      <line x1="12" y1="17" x2="12" y2="21" />
      <line x1="8" y1="21" x2="16" y2="21" />
      <path d="M10 7.5v5l4-2.5z" />
    </SvgIcon>
  )
}

/** Slide list: a grid of four slides. */
export function IconReaderGrid(props: IconProps) {
  return (
    <SvgIcon {...props}>
      <rect x="3" y="4" width="8" height="6.5" rx="1.5" />
      <rect x="13" y="4" width="8" height="6.5" rx="1.5" />
      <rect x="3" y="13.5" width="8" height="6.5" rx="1.5" />
      <rect x="13" y="13.5" width="8" height="6.5" rx="1.5" />
    </SvgIcon>
  )
}
